import { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        email,
        password,
        role,
      });

      login(res.data);

      if (res.data.user.role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/dashboard');
      }
    } catch (err) {
      alert('Login failed: ' + (err.response?.data?.error || 'Invalid credentials'));
    }
  };

  return (
    <div
      style={{
        height: '100vh',
        display: 'flex',
        fontFamily: 'Poppins, sans-serif',
        background: 'linear-gradient(135deg, #0f2027, #203a43, #2c5364)',
      }}
    >
      
      {/* LEFT SIDE (Branding / Quiz Feel) */}
      <div
        style={{
          flex: 1,
          color: 'white',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          padding: '40px',
        }}
      >
        <img
          src="/logo.png"
          alt="logo"
          style={{
            width: '120px',
            marginBottom: '20px',
            borderRadius: '50%',
            boxShadow: '0 0 20px rgba(255,255,255,0.3)'
          }}
        />

        <h1 style={{ fontWeight: '700' }}>Quiz Hub</h1>
        <p style={{ opacity: 0.8, textAlign: 'center', maxWidth: '300px' }}>
          Test your knowledge, climb the leaderboard, and challenge yourself with smart quizzes.
        </p>

        <div style={{ marginTop: '30px', fontSize: '14px', opacity: 0.7 }}>
          🎯 Real-time Results <br />
          🏆 Leaderboard System <br />
          📊 Performance Analytics
        </div>
      </div>

      {/* RIGHT SIDE (Login Form) */}
      <div
        style={{
          flex: 1,
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
        }}
      >
        <div
          style={{
            width: '380px',
            padding: '40px',
            borderRadius: '15px',
            background: 'rgba(255,255,255,0.1)',
            backdropFilter: 'blur(12px)',
            boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
            color: 'white',
          }}
        >
          <h3 style={{ textAlign: 'center', marginBottom: '30px' }}>
            Welcome Back 👋
          </h3>

          <form onSubmit={handleSubmit}>
            
            {/* Email */}
            <div className="mb-3">
              <label>Email</label>
              <div className="input-group">
                <span className="input-group-text bg-dark text-white">
                  <i className="fas fa-user"></i>
                </span>
                <input
                  type="email"
                  className="form-control bg-transparent text-white"
                  placeholder="Enter email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  style={{ border: 'none' }}
                />
              </div>
            </div>

            {/* Password */}
            <div className="mb-3">
              <label>Password</label>
              <div className="input-group">
                <span className="input-group-text bg-dark text-white">
                  <i className="fas fa-lock"></i>
                </span>
                <input
                  type="password"
                  className="form-control bg-transparent text-white"
                  placeholder="Enter password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  style={{ border: 'none' }}
                />
              </div>
            </div>

            {/* Role */}
            <div className="mb-3">
              <label>Select Role</label>
              <select
                className="form-control bg-dark text-white"
                value={role}
                onChange={(e) => setRole(e.target.value)}
                required
              >
                <option value="">Choose role</option>
                <option value="student">Student</option>
                <option value="admin">Admin</option>
              </select>
            </div>

            {/* Button */}
            <button
              type="submit"
              className="btn w-100"
              style={{
                background: 'linear-gradient(45deg, #ff416c, #ff4b2b)',
                color: 'white',
                fontWeight: '600',
                border: 'none',
                padding: '10px',
                marginTop: '10px',
              }}
            >
              Login
            </button>
          </form>

          <div className="text-center mt-3">
            <span style={{ fontSize: '14px' }}>
              Don’t have an account?{' '}
              <a href="/register" style={{ color: '#00c6ff' }}>
                Sign Up
              </a>
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
